'use strict';
/* GENESIS is a deterministic, deliberately multiscale educational model. */
const STORAGE_KEY='genesis-living-genome-v1';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function hashSeed(s){let h=2166136261;for(const c of String(s)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
class RNG{constructor(seed){this.s=seed>>>0||1}next(){this.s=(Math.imul(this.s,1664525)+1013904223)>>>0;return this.s/4294967296}int(n){return Math.floor(this.next()*n)}pick(a){return a[this.int(a.length)]}normal(){return Math.sqrt(-2*Math.log(Math.max(.000001,this.next())))*Math.cos(6.283*this.next())}}
const FUNCTIONS=[['ATP synthase','energy metabolism'],['Catalase','oxidative stress response'],['Aquaporin','water transport'],['Heat-shock protein','protein folding'],['DNA ligase','genome maintenance'],['Photoreceptor','light sensing'],['Membrane transporter','nutrient uptake'],['Cell-cycle kinase','cell division'],['pH regulator','acid tolerance'],['Adhesin','surface attachment'],['RNA polymerase','transcription'],['Ion channel','membrane signaling']];
const CODONS=['ATG','GCT','TTC','GAA','CAG','TGG','AAC','CTG','GAC','TAT','CCG','AAG','GTT','AGC','ACT','GCA','CGT','TTG','CAA','GGT'];
function makeGene(rng,i){let [name,role]=FUNCTIONS[i%FUNCTIONS.length], codonN=5+rng.int(8), coding='ATG';for(let j=1;j<codonN-1;j++)coding+=rng.pick(CODONS.slice(1));coding+='TAA';let intron='';for(let j=0;j<20+rng.int(35);j++)intron+='ATCG'[rng.int(4)];let exonStart=100+rng.int(140), promoter='TATAAA';let regulation=['constitutive','nutrient-responsive','stress-inducible','developmental'][rng.int(4)];return{id:`G${String(i+1).padStart(2,'0')}`,name,role,chromosome:1+rng.int(3),start:exonStart,end:exonStart+coding.length+intron.length+16,promoter,enhancer:rng.pick(['CAAT','GC-box','HSE','CRE']),coding,intron,regulation,activity:.34+rng.next()*.62,dominance:rng.pick(['dominant','recessive','additive']),mutation:null,epi:rng.next()*.14}}
function makeGenome(seed,source=null){let rng=new RNG(hashSeed(seed)),genes=source?source.genes.map(g=>({...g})):Array.from({length:8+rng.int(4)},(_,i)=>makeGene(rng,i));let noncoding='';for(let i=0;i<120;i++)noncoding+='ATCG'[rng.int(4)];return{id:`GX-${hashSeed(seed).toString(16).toUpperCase().slice(0,6)}`,seed,chromosomes:source?source.chromosomes:2+rng.int(3),genes,noncoding,sequence:'',generation:source?.generation||0,origin:source?.id||null,mutations:source?source.mutations||0:0}}
function transcribe(g){return g.coding.replaceAll('T','U')}
function translate(rna){const aa=['M','A','F','E','Q','W','N','L','D','Y','P','K','V','S','T','R','L','Q','G'];let out='';for(let i=0;i<rna.length-3;i+=3){let c=rna.slice(i,i+3);if(c==='UAA'||c==='UAG'||c==='UGA')break;out+=aa[hashSeed(c)%aa.length]}return out||'M'}
function gc(seq){return seq?((seq.match(/[GC]/g)||[]).length/seq.length*100):0}
function genomeSequence(g){let s='';for(const gene of g.genes){s+=gene.promoter+gene.enhancer+gene.coding.slice(0,Math.floor(gene.coding.length/2))+gene.intron+gene.coding.slice(Math.floor(gene.coding.length/2))}return s+g.noncoding}
function traitMap(g,env){let map={};for(const gene of g.genes){let envFactor=1;if(gene.regulation==='stress-inducible')envFactor=clamp(.24+env.stress*.95,.18,1);if(gene.regulation==='nutrient-responsive')envFactor=clamp(.22+env.nutrients*.9,.2,1);if(gene.regulation==='developmental')envFactor=.45+Math.sin(g.generation*.11)*.2;map[gene.name]=clamp(gene.activity*envFactor*(1-gene.epi)*(gene.mutation?.8:1),.02,1)}return map}
function expressionProfile(g,env){const exp=traitMap(g,env);return g.genes.map(x=>({...x,expression:exp[x.name],protein:translate(transcribe(x))}))}
function initialState(seed,source){let rng=new RNG(hashSeed(seed)),genome=makeGenome(seed,source),env={temperature:20+rng.next()*12,radiation:rng.next()*.18,nutrients:.45+rng.next()*.5,oxygen:.42+rng.next()*.55,water:.45+rng.next()*.5,ph:6.4+rng.next()*1.8,chemical:0};genome.sequence=genomeSequence(genome);let exp=traitMap(genome,env),fitness=clamp(.62+Object.values(exp).reduce((a,b)=>a+b,0)/Object.keys(exp).length*.2-rng.next()*.12,.3,.95);return{seed,genome,env,tick:0,generation:0,population:120+rng.int(280),fitness,viability:91+rng.next()*8,atp:2.1+rng.next()*1.3,damage:rng.next()*7,senescence:rng.next()*4,diversity:.08+rng.next()*.12,history:[],events:[{tick:0,type:'origin',text:'A viable population establishes in the tidal microhabitat.'}],samples:{dna:false,rna:false},labResults:[],notebook:[],archive:[],speed:1,playing:false,selectedGene:0,cellCount:2400+rng.int(700),liveCells:0,sourceId:source?.id||null,experimentCount:0}}
function storeState(){try{const {playing,...safe}=S;localStorage.setItem(STORAGE_KEY,JSON.stringify(safe))}catch(e){console.warn('Persistence unavailable',e)}}
function loadState(){try{let x=JSON.parse(localStorage.getItem(STORAGE_KEY));if(x?.genome){x.playing=false;return x}}catch(e){}return null}
let S=loadState()||initialState(`GEN-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`);
let currentView='overview',activeProtocol='DNA extraction',toastTimer;
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
function f(n,d=1){return Number(n).toFixed(d)}
function tick(){if(!S.playing)return;const r=new RNG(hashSeed(S.seed+':'+S.tick));S.tick++;let e=S.env,stress=clamp(Math.abs(e.temperature-24)/22+e.radiation*.7+e.chemical*.5+Math.abs(e.ph-7.3)*.1,0,1.4);let expressions=traitMap(S.genome,e),metabolic=expressions['ATP synthase']||.5,repair=expressions['DNA ligase']||.5,transport=expressions['Membrane transporter']||.5;S.atp=clamp(S.atp+.045*metabolic*e.oxygen+.025*e.nutrients-.035-stress*.018,.3,7);S.damage=clamp(S.damage+stress*.16-repair*.1+r.normal()*.12,0,100);S.viability=clamp(S.viability+.025*(S.atp-2.7)-stress*.17-S.damage*.001+r.normal()*.07,0,100);S.senescence=clamp(S.senescence+.007+stress*.012,0,100);let growth=(S.viability/100)*(.35+transport*.45)*e.nutrients;if(r.next()<.32)S.population=clamp(Math.round(S.population+growth*2-r.next()*1.7),15,6000);S.cellCount=Math.round(S.population*12+S.viability*8);S.liveCells=Math.round(S.cellCount*S.viability/100);S.fitness=clamp(.25+S.viability*.005+metabolic*.13+transport*.08-stress*.13,0,1);if(S.tick%16===0)e.nutrients=clamp(e.nutrients-.015+r.next()*.026,.1,1);if(S.tick%25===0)generationStep();if(S.tick%4===0){storeState();if(currentView==='overview'||currentView==='evolution')render()}}
function generationStep(){let old=S.genome, rng=new RNG(hashSeed(S.seed+':generation:'+S.generation)),child=makeGenome(`${S.seed}:${S.generation+1}`,old);child.generation=S.generation+1;child.mutations=old.mutations;let mutationRate=.001+(S.env.radiation*.008)+(S.damage/100*.002);for(const g of child.genes){if(rng.next()<mutationRate){g.mutation={from:g.coding[rng.int(g.coding.length)],position:rng.int(g.coding.length)};let pos=g.mutation.position,base=g.coding[pos];g.coding=g.coding.slice(0,pos)+rng.pick('ATCG'.replace(base,''))+g.coding.slice(pos+1);g.activity=clamp(g.activity+rng.normal()*.08,.05,1);child.mutations++;}}
S.generation++;S.genome=child;S.genome.sequence=genomeSequence(child);S.diversity=clamp(S.diversity+mutationRate*.8+rng.normal()*.002,.01,.8);S.population=Math.round(clamp(S.population*(.91+S.fitness*.2+rng.normal()*.04),12,7000));S.history.push({generation:S.generation,tick:S.tick,fitness:S.fitness,population:S.population,diversity:S.diversity,genomeId:child.id,mutations:child.mutations});if(S.history.length>250)S.history.shift();S.events.unshift({tick:S.tick,type:'generation',text:`Generation ${S.generation} inherits ${child.mutations} recorded sequence variant${child.mutations===1?'':'s'}.`});if(S.events.length>14)S.events.pop();storeState()}
setInterval(tick,650);

