setInterval(tick,650);
function pageHead(kicker,title,sub,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="heading-right">${extra}</div></div>`}
function metric(label,value,detail,trend=''){return `<div class="card metric-card"><span class="metric-label">${label}</span><span class="trend">${trend}</span><div class="metric-value">${value}</div><div class="metric-detail">${detail}</div></div>`}
function eventRows(){return S.events.slice(0,4).map(e=>`<div class="event-row"><i class="event-marker ${e.type==='generation'?'lime':e.type==='lab'?'orange':''}"></i><div class="event-copy">${e.text}<small>${e.type==='origin'?'SYSTEM ORIGIN':e.type==='generation'?'INHERITANCE EVENT':'LAB NOTE'} · T+${e.tick}</small></div><span class="event-time">${e.tick===S.tick?'NOW':`${S.tick-e.tick} T`}</span></div>`).join('')}
function drawEcosystem(){const c=$('#ecosystem-canvas');if(!c)return;const rect=c.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2),w=rect.width,h=rect.height;if(!w||!h)return;c.width=w*dpr;c.height=h*dpr;let ctx=c.getContext('2d');ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);let rng=new RNG(hashSeed(S.seed+':ecosystem'));let cells=Math.min(88,Math.round(34+S.population/85));for(let i=0;i<cells;i++){let x=rng.next()*w,y=rng.next()*h,r=2+rng.next()*4,phase=(S.tick*.04+rng.next()*8),glow=.55+.45*Math.sin(phase);ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=i%13===0?`rgba(240,165,104,${.35*glow})`:i%5===0?`rgba(98,216,192,${.36*glow})`:`rgba(198,243,107,${.38*glow})`;ctx.shadowBlur=9*glow;ctx.shadowColor=ctx.fillStyle;ctx.fill();ctx.shadowBlur=0;if(i<12){ctx.beginPath();ctx.arc(x,y,r+5+Math.sin(phase)*2,0,Math.PI*2);ctx.strokeStyle=`rgba(156,211,137,${.08*glow})`;ctx.lineWidth=.6;ctx.stroke()}}
// Environmental gradients / subtle substrate topology
ctx.strokeStyle='#8cbb8c0c';ctx.lineWidth=1;for(let i=0;i<5;i++){ctx.beginPath();let y=h*(.18+i*.16);ctx.moveTo(0,y);for(let x=0;x<=w;x+=12)ctx.lineTo(x,y+Math.sin(x*.014+i+S.tick*.008)*5);ctx.stroke()}}
function drawTrend(){const c=$('#trend-canvas');if(!c)return;let r=c.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);c.width=r.width*dpr;c.height=r.height*dpr;let ctx=c.getContext('2d');ctx.scale(dpr,dpr);let w=r.width,h=r.height,history=S.history.slice(-24),vals=history.length?history.map(x=>x.fitness):Array.from({length:18},(_,i)=>S.fitness-Math.sin(i*.65)*.05+i*.001);let min=Math.min(...vals)-.04,max=Math.max(...vals)+.05;ctx.strokeStyle='#22322b';ctx.lineWidth=1;for(let i=1;i<4;i++){let y=h*i/4;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}let pts=vals.map((v,i)=>({x:i/(vals.length-1||1)*w,y:h-((v-min)/(max-min||1))*(h-18)-8}));let grad=ctx.createLinearGradient(0,0,0,h);grad.addColorStop(0,'#c6f36b33');grad.addColorStop(1,'#c6f36b00');ctx.beginPath();ctx.moveTo(pts[0].x,h);pts.forEach(p=>ctx.lineTo(p.x,p.y));ctx.lineTo(w,h);ctx.closePath();ctx.fillStyle=grad;ctx.fill();ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle='#c6f36b';ctx.lineWidth=1.7;ctx.stroke();pts.forEach((p,i)=>{if(i===pts.length-1){ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);ctx.fillStyle='#d9f99c';ctx.fill()}})}
function overview(){let exp=expressionProfile(S.genome,S.env);let common=exp.sort((a,b)=>b.expression-a.expression)[0]?.name||'Microbial isolate';let title=common==='Photoreceptor'?'Lumen adaptans':'Pelagomyces genesis';return `${pageHead('OBSERVATION LOG · CYCLE ${String(S.tick).padStart(4,'0')}','Living system','A self-contained microbial world, evolving under observation.',`<button class="subtle-button" data-action="sample">＋ Collect sample</button><button class="action-button primary" data-action="toggle">${S.playing?'Ⅱ  Pause':'▶  Resume'}</button>`)}
<div class="overview-grid"><section class="card ecosystem-card"><div class="card-head"><div><div class="card-title">Tidal microhabitat <span class="card-meta">/ closed ecosystem</span></div></div><span class="tag green">● ${S.playing?'DYNAMICS ACTIVE':'OBSERVING'}</span></div><div class="world-canvas-wrap"><canvas id="ecosystem-canvas"></canvas><div class="world-overlay"><strong>PELAGIC ZONE 01</strong><span>depth 0.8 mm · 21.4 °C</span></div><div class="world-legend"><span><i class="legend-dot"></i>COLONIES</span><span><i class="legend-dot cyan"></i>NUTRIENT</span><span><i class="legend-dot orange"></i>STRESS</span></div></div><div class="ecosystem-foot"><span>POPULATION FIELD · ${S.population.toLocaleString()} ORGANISMS</span><div class="ecosystem-controls"><button class="tiny-control ${S.speed===1?'selected':''}" data-speed="1">1×</button><button class="tiny-control ${S.speed===4?'selected':''}" data-speed="4">4×</button><button class="tiny-control ${S.speed===10?'selected':''}" data-speed="10">10×</button></div></div></section>
<section class="card organism-card"><div class="organism-top"><div><span class="specimen-id">SPECIMEN ${S.genome.id}</span><div class="species-name">${title}</div><div class="species-common">Novel clade · unicellular phototroph</div></div><span class="live-tag">● VIABLE</span></div><div class="organism-art"><span class="cell-label one">CELL WALL</span><div class="cell-visual"></div><span class="cell-label two">CYTOPLASM</span></div><div class="organism-stats"><div class="mini-stat"><span>GENERATION</span><strong>${String(S.generation).padStart(3,'0')}</strong></div><div class="mini-stat"><span>FITNESS INDEX</span><strong class="stat-good">${f(S.fitness*100,1)}<small>%</small></strong></div><div class="mini-stat"><span>GENOME</span><strong>${(S.genome.sequence.length/1000).toFixed(2)}<small>kb</small></strong></div><div class="mini-stat"><span>GC CONTENT</span><strong>${f(gc(S.genome.sequence),1)}<small>%</small></strong></div></div></section></div>
<div class="metric-strip">${metric('VIABLE CELLS',`${Math.round(S.cellCount*S.viability/100).toLocaleString()}`,`of ${S.cellCount.toLocaleString()} observed cells`,'↗ 2.4%')}${metric('ATP · MEAN',`${f(S.atp,2)}`,`mmol / L · model proxy`,'↗ 0.08')}${metric('DNA DAMAGE',`${f(S.damage,1)}%`,`relative lesion burden`,'↘ 0.3%')}${metric('GENETIC DIVERSITY',`${f(S.diversity*100,1)}%`,`heterozygosity proxy`,'↗ 0.2%')}</div>
<div class="lower-grid"><section class="card"><div class="card-head"><span class="card-title">Fitness trajectory <span class="card-meta">/ generations</span></span><span class="tag">${S.history.length} DATA POINTS</span></div><div class="chart-area"><canvas id="trend-canvas"></canvas></div><div class="chart-labels"><span>G${Math.max(0,S.generation-23)}</span><span>POPULATION FITNESS · RELATIVE INDEX</span><span>G${S.generation}</span></div></section><section class="card"><div class="card-head"><span class="card-title">Field observations</span><button class="tiny-control" data-view="notebook">NOTEBOOK →</button></div><div class="event-list">${eventRows()}</div></section></div>`}
function geneRows(){return S.genome.genes.map((g,i)=>`<div class="gene-row" data-gene="${i}"><span class="gene-id">${g.id} ${g.mutation?'⚠':''}</span><span class="gene-function">${g.name}<small>${g.regulation.toUpperCase()} · chr ${g.chromosome}</small></span><div class="expression-bar"><i style="width:${Math.round(traitMap(S.genome,S.env)[g.name]*100)}%"></i></div><span class="gene-value">${f(traitMap(S.genome,S.env)[g.name],2)}×</span></div>`).join('')}
function genomeView(){let g=S.genome.genes[S.selectedGene]||S.genome.genes[0],slice=g.promoter+g.enhancer+g.coding.slice(0,18)+g.intron.slice(0,16)+g.coding.slice(18),sequence=slice.split('').map((x,i)=>`<span class="${i<g.promoter.length?'promoter':i>=g.promoter.length+g.enhancer.length&&i<g.promoter.length+g.enhancer.length+g.coding.length?'highlight':''}">${x}</span>`).join('');return `${pageHead('MOLECULAR RECORD · ${S.genome.id}','Genome explorer','A living sequence, transcribed and translated into phenotype.',`<button class="subtle-button" data-action="sequence">${S.samples.dna?'↻ Resequence':'⌁ Sequence genome'}</button><button class="action-button primary" data-action="save-genome">＋ Archive genome</button>`)}<div class="metric-strip">${metric('ASSEMBLED LENGTH',`${S.genome.sequence.length.toLocaleString()}<small> bp</small>`,'estimated · simulated reference')}${metric('GC CONTENT',`${f(gc(S.genome.sequence),1)}<small>%</small>`,'sequence composition')}${metric('PREDICTED GENES',S.genome.genes.length,'annotated ORFs')}${metric('CHROMOSOMES',S.genome.chromosomes,'haploid model')}</div><div class="section-grid"><section class="card"><div class="card-head"><span class="card-title">Gene annotation <span class="card-meta">/ ${S.genome.genes.length} loci</span></span><span class="tag green">LIVE EXPRESSION</span></div><div class="gene-list">${geneRows()}</div></section><div style="display:grid;gap:14px;align-content:start"><section class="card"><div class="card-head"><span class="card-title">Locus sequence · ${g.id}</span><span class="tag">CHROMOSOME ${g.chromosome}</span></div><div class="gene-detail"><div class="sequence-display"><div>${sequence}</div><div class="sequence-caption"><span>5′ → 3′ · CODING STRAND</span><span>${slice.length} BP</span></div></div><div class="chip-row"><span class="chip">PROMOTER ${g.promoter}</span><span class="chip">ENHANCER ${g.enhancer}</span><span class="chip">${g.intron.length} BP INTRON</span></div><p><strong style="color:#dce4dd">${g.name}</strong> — ${g.role}. ${g.regulation} regulation. Predicted peptide: <span style="color:var(--lime);font-family:var(--mono)">${translate(transcribe(g))}</span></p><div class="mini-stat"><span>EXPRESSION LEVEL · RELATIVE MODEL UNITS</span><strong class="stat-good">${f(traitMap(S.genome,S.env)[g.name],3)}<small>× baseline</small></strong></div></div></section><section class="card"><div class="card-head"><span class="card-title">Sequence context</span><span class="card-meta">NON-CODING DNA</span></div><div class="gene-detail"><div class="sequence-display">${S.genome.noncoding.slice(0,84).split('').map((x,i)=>`<span style="color:${['#9bafa3','#9bd8c3','#d0b77e','#a6c078'][i%4]}">${x}</span>`).join('')}<div class="sequence-caption"><span>INTERGENIC REGION</span><span>84 BP SHOWN</span></div></div><p>Non-coding sequence contributes regulatory context in this model; sequence shown is generated, not a reference biological genome.</p></div></section></div></div>`}

